    std::string name_;
    int count_;
};

int main() {
    std::string name;
    int count;
    bool first = true;
    while (std::cin >> name >> count) {
        if (!first) {
            std::cout << ", ";
        }
        std::cout << Item(name, count) << "";
        first = false;
    }
    std::cout << '\n';
    return 0;
}

